queries.AUDIT:
with component_audit as (select 'public.audit_events' relation,count(*) row_count,
   encode(pg_catalog.sha256(pg_catalog.convert_to(coalesce(string_agg(row_hash,'|' order by row_hash),''),'UTF8')),'hex') row_fingerprint
   from (select encode(pg_catalog.sha256(pg_catalog.convert_to(to_jsonb(t)::text,'UTF8')),'hex') row_hash from "public"."audit_events" t offset 0) hashed_rows)
select jsonb_build_object('version','CONTACT_CANONICAL_COMPONENT_V1','component','AUDIT','counts',(select jsonb_build_array(row_count::text) from component_audit),'digest',(select row_fingerprint from component_audit))::text;
